var t=`0198-coca-massegada`;var i=`world-0198`;var a=`AD`;var s=`southern-europe`;var r=8;var o=69;var g={en:`Coca Massegada`,ua:`Кока массегада`};var d={en:`A classic dish from Andorra, featuring chicken egg, whole cow milk, lemon zest. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Андорра. Основні складники: куряче яйце, цільне коров'яче молоко, цедра лимона. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var u=[{en:`Beat the listed ingredients until pale and light; ensure butter and eggs are at room temperature when specified.`,ua:`Збийте зазначені складники до світлої пишної маси; за потреби використовуйте масло та яйця кімнатної температури.`,t:[`creaming-butter-sugar`,`whisking`],m:10,i:[[`unsalted-butter`,135,`g`],[`white-granulated-sugar`,200,`g`],[`chicken-egg`,4,`pcs`]]},{en:`Gently fold in the remaining dry or wet ingredients just until homogeneous, without deflating the mixture.`,ua:`Обережно вмішайте решту сухих або рідких складників лише до однорідності, не осаджуючи масу.`,t:[`folding-batter`],m:8,i:[[`all-purpose-flour`,365,`g`],[`whole-cow-milk`,160,`ml`],[`baking-powder`,10,`g`],[`lemon-zest`,8,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:10,i:[]},{en:`Bake in a preheated 180°C oven for about 38 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 38 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:38,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`powdered-sugar`,35,`g`]]}];var l={slug:t,id:i,country:`AD`,region:s,servings:8,minutes:69,title:g,text:d,steps:u};export{a as country,l as default,i as id,o as minutes,s as region,r as servings,t as slug,u as steps,d as text,g as title};